-- 1. Schema migration: Ensure parent_id and extra columns exist in categories and settings
alter table public.categories add column if not exists parent_id uuid references public.categories(id) on delete cascade;
alter table public.categories alter column parent_id drop not null;
alter table public.categories add column if not exists image_url text;
alter table public.menu_items add column if not exists half_price numeric(10,2);
alter table public.restaurant_settings add column if not exists discount_percent numeric(5,2) default 0;
alter table public.restaurant_settings add column if not exists discount_note text default '';
alter table public.restaurant_settings add column if not exists upi_id text default '';
alter table public.restaurant_settings add column if not exists qr_image_url text default '';

-- Remove restrictive unique constraint on name if present so subcategories can be named freely
alter table public.categories drop constraint if exists categories_name_key;

-- 2. Update restaurant profile settings
  id, restaurant_name, whatsapp_number, contact_phone, address, opening_hours, delivery_charge, minimum_order_amount, discount_percent, discount_note, upi_id
) values (
  1,
  'Radhe Krushna Food Zone',
  '917069300077',
  '7069300077 / 9979678889',
  'AB-3, Mile Stone, Anand Vidhyanagar Road, Anand - 388 001',
  'Daily · 11:00 AM – 11:00 PM',
  30.00,
  100.00,
  0.00,
  'Special Offer available!',
  '7069300077@upi'
)
on conflict (id) do update set
  restaurant_name = excluded.restaurant_name,
  whatsapp_number = excluded.whatsapp_number,
  contact_phone = excluded.contact_phone,
  address = excluded.address,
  opening_hours = excluded.opening_hours,
  upi_id = coalesce(nullif(public.restaurant_settings.upi_id, ''), excluded.upi_id);

-- 3. Clear existing menu items and categories for a clean hierarchical build
delete from public.menu_items;
delete from public.categories;

